using var workspace = new AdhocWorkspace();
var project = workspace.AddProject("proof", LanguageNames.CSharp)
 .WithMetadataReferences(references)
 .WithCompilationOptions(new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary)
  .WithSpecificDiagnosticOptions(new Dictionary<string, ReportDiagnostic> { ["IDE0004"] = ReportDiagnostic.Info }));
var document = project.AddDocument("proof.cs", source);
var features = Assembly.Load("Microsoft.CodeAnalysis.CSharp.Features");
var analyzer = (DiagnosticAnalyzer)Activator.CreateInstance(features.GetType(
 "Microsoft.CodeAnalysis.CSharp.RemoveUnnecessaryCast.CSharpRemoveUnnecessaryCastDiagnosticAnalyzer", true)!, true)!;
var fix = (CodeFixProvider)Activator.CreateInstance(features.GetType(
