var compilation = (await document.Project.GetCompilationAsync())!;
var diagnostics = await compilation.WithAnalyzers([analyzer]).GetAnalyzerDiagnosticsAsync();
var diagnostic = diagnostics.Single(d => d.Id == "IDE0004");
Console.WriteLine(diagnostic);
var actions = new List<CodeAction>();
await fix.RegisterCodeFixesAsync(new CodeFixContext(document, diagnostic, (a, _) => actions.Add(a), CancellationToken.None));
var operations = await actions.Single().GetOperationsAsync(CancellationToken.None);
var changed = operations.OfType<ApplyChangesOperation>().Single().ChangedSolution.GetDocument(document.Id)!;
Console.WriteLine("AFTER IDE0004");
Console.WriteLine(await changed.GetTextAsync());
Console.WriteLine("BEFORE RUNTIME");
Execute(compilation);
Console.WriteLine("AFTER RUNTIME");
Execute((await changed.Project.GetCompilationAsync())!);

static void Execute(Compilation compilation) {
 using var stream = new MemoryStream();
 var emitted = compilation.WithAssemblyName("proof_" + Guid.NewGuid().ToString("N")).Emit(stream);
 if (!emitted.Success) throw new InvalidOperationException(string.Join("\n", emitted.Diagnostics));
 stream.Position = 0;
 var load = new AssemblyLoadContext("proof", true);
 try { load.LoadFromStream(stream).GetType("Probe")!.GetMethod("Run")!.Invoke(null, null); }
 finally { load.Unload(); }
